  for f in list(streams.values())+[framefile,syncfile]:
   if f:f.close()
  videos=[]
  for name,(proc,log) in encoders.items():
   try:proc.stdin.close();assert proc.wait(timeout=180)==0;videos.append(name+'.mkv')
   except Exception as exc:
