"""Owned-scene teardown barriers and fresh-client baseline restoration, CARLA0.9.15."""
import hashlib,json,time

def restore(carla,client,world,owned,previous,weather,prior_path,prior_xml,host,port,directory):
 def event(stage,**values):
  with (directory/'cleanup-progress-v3.jsonl').open('a') as f:f.write(json.dumps(dict(at=time.time(),stage=stage,**values),allow_nan=False)+'\n')
 ids={a.id for a in owned};event('stop_all_owned_sensor_callbacks',owned_actor_ids=sorted(ids))
 for a in owned:
  if a.type_id.startswith('sensor.') and a.is_listening:a.stop()
 event('batch_destroy_owned_actors')
 order=sorted(owned,key=lambda a:not a.type_id.startswith('sensor.'))
 fresh_destroy=carla.Client(host,port,2);fresh_destroy.set_timeout(30)
 responses=fresh_destroy.apply_batch_sync([carla.command.DestroyActor(a.id) for a in order],False)
 if any(r.has_error() for r in responses):raise RuntimeError('Owned actor batch destruction failed: '+str([r.error for r in responses if r.has_error()]))
 for _ in range(2):world.tick()
 remaining=[{'id':a.id,'type':a.type_id} for a in world.get_actors() if a.id in ids or a.type_id.startswith(('vehicle.','walker.','sensor.'))]
 if remaining:raise RuntimeError('Native dynamic actors remain after teardown barrier: '+str(remaining))
 event('native_actor_absence_confirmed',remaining=remaining)
 world.apply_settings(previous)
 first=world.wait_for_tick(30);second=world.wait_for_tick(30)
 if not second.frame>first.frame:raise RuntimeError('No native asynchronous frame advance before map restoration')
 event('native_async_frames_confirmed',frames=[first.frame,second.frame])
 fresh=carla.Client(host,port,2);fresh.set_timeout(180)
 event('load_prior_native_map_with_settings_preserved',native_map_path=prior_path)
 restored=fresh.load_world(prior_path,False)
 restored.set_weather(weather);restored.apply_settings(previous)
 actual=hashlib.sha256(restored.get_map().to_opendrive().encode()).hexdigest();expected=hashlib.sha256(prior_xml.encode()).hexdigest()
 if actual!=expected:raise RuntimeError('Prior native map hash mismatch')
 for observed,target in [(restored.get_settings(),previous),(restored.get_weather(),weather)]:
  for k in dir(target):
   if k.startswith('_'):continue
   v=getattr(target,k)
   if not isinstance(v,(bool,int,float,type(None))):continue
   got=getattr(observed,k)
   if isinstance(v,(int,float)) and not isinstance(v,bool):
    if abs(got-v)>1e-5:raise RuntimeError('Prior native settings/weather mismatch: '+k)
   elif got!=v:raise RuntimeError('Prior native settings/weather mismatch: '+k)
 event('prior_native_baseline_verified',map_sha256=actual)
 return {'restored':True,'previous_map_name':restored.get_map().name,'previous_map_sha256':actual,'settings_and_weather_verified':True,'restoration_method':'sensor stop, ordered batch destruction, native absence and asynchronous-frame barriers; fresh bounded client native-map reload preserving settings','cleanup_implementation':'cleanup_v3.py'}

"""Prospective tick-neutral native two-actor capture helper; never connects or drives."""
import math
from footprint_gap import gap

def snapshot(actor):
 from original_observations import actor_state
 state=actor_state(actor);pose=actor.get_transform();box=actor.bounding_box
 local=[[p.x,p.y,p.z] for p in box.get_local_vertices()];matrix=pose.get_matrix();native=state['body_vertices_m']
 predicted=[[sum(matrix[row][col]*([*p,1][col]) for col in range(4)) for row in range(3)] for p in local]
 error=max(min(math.dist(p,q) for q in native) for p in predicted)
 if len(native)!=8 or error>1e-4:raise ValueError('Native body vertices/offset/rotation differ from actual instance pose')
 state.update(body_vertices_native_m=native,body_local_vertices_m=local,pose_native_matrix=matrix,
  native_box_extent_m=[box.extent.x,box.extent.y,box.extent.z],native_box_offset_m=[box.location.x,box.location.y,box.location.z],native_box_rotation_deg={'yaw':box.rotation.yaw,'pitch':box.rotation.pitch,'roll':box.rotation.roll},native_pose_check_maximum_error_m=error)
 control=actor.get_control();state['applied_control']={k:getattr(control,k) for k in ('throttle','brake','steer','hand_brake','reverse','manual_gear_shift','gear')}
 return state

def capture_pair(ego,apparatus,frame,time_s,actual_follower_inputs):
 if ego.id==apparatus.id:raise ValueError('Distinct native subject and apparatus required')
 a,b=snapshot(ego),snapshot(apparatus)
 if a['blueprint']!='vehicle.tesla.model3' or b['blueprint']!='vehicle.carlamotors.firetruck':raise ValueError('Actual native assets differ from prospective comparison')
 distance=gap(a['body_vertices_native_m'],b['body_vertices_native_m'])
 packet={'frame':frame,'time_s':time_s,'ego':a,'apparatus':b,'native_nearest_footprint_gap_m':distance,
  'centre_distance_diagnostic_m':math.dist([sum(v[k] for v in a['body_vertices_native_m'])/8 for k in (0,1)],[sum(v[k] for v in b['body_vertices_native_m'])/8 for k in (0,1)]),
  'follower_controller_inputs':actual_follower_inputs,'response_purpose_native_observation':None,
  'siren_native_observation':None,'purpose_provenance':'Separate user-authored synthetic condition; neither model/lamp nor siren establishes purpose'}
 participant_row={'time_s':time_s,'value':{'frame':frame,'ego':a,'apparatus':b}}
 return packet,participant_row

"""Full native-box footprint separation; no centre or component-gap substitution."""
import math
from shapely.geometry import MultiPoint

def footprint(vertices):
    if len(vertices)!=8 or any(len(v)!=3 or any(not isinstance(x,(int,float)) or isinstance(x,bool) or not math.isfinite(x) for x in v) for v in vertices):
        raise ValueError('Eight finite actual native world-space box vertices required')
    polygon=MultiPoint([(v[0],v[1]) for v in vertices]).convex_hull
    if polygon.geom_type!='Polygon' or polygon.area<=0 or not polygon.is_valid:
        raise ValueError('Degenerate native footprint')
    return polygon

def gap(first_vertices,second_vertices):
    """Minimum Euclidean distance of complete horizontal projected native boxes, m."""
    return footprint(first_vertices).distance(footprint(second_vertices))

def distance_constraint(first_vertices,second_vertices,minimum_m):
    if isinstance(minimum_m,bool) or not isinstance(minimum_m,(int,float)) or not math.isfinite(minimum_m) or minimum_m<0:
        raise ValueError('Finite nonnegative distance required')
    distance=gap(first_vertices,second_vertices)
    return {'nearest_footprint_gap_m':distance,'minimum_required_m':minimum_m,
            'every_footprint_point_satisfies_minimum':distance>=minimum_m,
            'convention':'minimum horizontal Euclidean polygon separation of all8actual native world box vertices for both actors',
            'native_precision':'uncalibrated; no exact equality claim'}

"""Native RGB/instance contrast-range instrument; no legal visibility standard.

A finite sampled, target/camera-specific optical observation, not geometric LOS.
